H='<!doctype html><meta charset=utf-8><link rel=stylesheet href="../../node_modules/misans/lib/Normal/MiSans-Medium.min.css"><link rel=stylesheet href="../../node_modules/misans/lib/Normal/MiSans-Bold.min.css"><link rel=stylesheet href="../../node_modules/misans/lib/Normal/MiSans-Heavy.min.css"><style>*{margin:0;padding:0;box-sizing:border-box}body{width:1920px;height:1080px;position:relative;overflow:hidden;font-family:MiSans;background:#F4F2EE}.p{position:absolute;left:64px;top:126px;width:1240px;height:698px;border-radius:28px;overflow:hidden;background:#fff}.pill{background:#2F6BFF;color:#fff;border-radius:14px;padding:0 18px}.tag{position:absolute;left:90px;top:152px;background:#E5322D;color:#fff;font:700 26px MiSans;padding:8px 18px;border-radius:10px}</style><body>'
def card(lab,sub,c):
    return f'<div style="width:300px;height:470px;border-radius:24px;background:{c};position:relative;overflow:hidden;box-shadow:0 14px 30px rgba(20,24,40,.12)"><div style="position:absolute;left:50%;top:44%;transform:translate(-50%,-50%);width:76px;height:76px;border-radius:50%;background:rgba(255,255,255,.9)"><div style="position:absolute;left:30px;top:22px;border-left:26px solid #2F6BFF;border-top:16px solid transparent;border-bottom:16px solid transparent"></div></div><div style="position:absolute;left:0;right:0;bottom:0;padding:22px;background:linear-gradient(transparent,rgba(0,0,0,.55));color:#fff"><div style="font:800 30px MiSans">{lab}</div><div style="font:500 20px MiSans;opacity:.85;margin-top:4px">{sub}</div></div></div>'
open('scenes/sc_R1.html','w').write(H+'<div class=p><div style="display:flex;gap:40px;justify-content:center;align-items:center;height:100%;padding-top:20px">'+card('海外爆款','换成我的人像和产品','linear-gradient(160deg,#C9D6F2,#8EA7DE)')+card('宠物用品','不养宠物，上传商品图就行','linear-gradient(160deg,#F2DCC9,#DDB08E)')+card('卡点节奏','几分钟做好，节奏卡得准','linear-gradient(160deg,#D5EDD9,#93C9A0)')+'</div></div><div class=tag>R1 成品待补：三条成品视频依次播放</div>')
open('scenes/sc_w47.html','w').write(H+'<div class=p style="padding:110px 96px"><div style="font:500 34px MiSans;color:#8A909A">做电商的朋友</div><div style="font:900 84px MiSans;color:#15171C;margin-top:18px;line-height:1.25">为什么一定要<br>用好 <span class=pill>豆包工作</span></div><div style="display:flex;gap:18px;margin-top:56px">'+''.join(f'<div style="font:700 28px MiSans;color:#2F6BFF;background:#EAF0FF;padding:12px 24px;border-radius:999px">{x}</div>' for x in ['生图','生视频','管素材','一站式'])+'</div></div>')
open('scenes/sc_k270.html','w').write(H+'<div class=p style="padding:96px 96px"><div style="font:500 34px MiSans;color:#8A909A">额外提一点</div><div style="font:900 76px MiSans;color:#15171C;margin-top:14px">按 <span class=pill>品类</span> 调整拆解侧重</div><div style="display:flex;gap:36px;margin-top:70px">'+''.join(f'<div style="flex:1;border-radius:22px;background:#F6F7FA;padding:34px 36px"><div style="font:500 28px MiSans;color:#8A909A">{a}</div><div style="font:900 46px MiSans;color:#15171C;margin-top:10px">{b}</div></div>' for a,b in [('卡点类视频','注明卡点节奏'),('口播类视频','更关注文案')])+'</div></div>')
def mini(lab,c): return f'<div style="width:200px;height:300px;border-radius:18px;background:{c};position:relative;overflow:hidden;box-shadow:0 10px 24px rgba(20,24,40,.12)"><div style="position:absolute;left:0;right:0;bottom:0;padding:16px;background:linear-gradient(transparent,rgba(0,0,0,.5));color:#fff;font:800 24px MiSans">{lab}</div><div style="position:absolute;right:12px;top:12px;width:34px;height:34px;border-radius:50%;background:#2F6BFF;color:#fff;font:900 22px/34px MiSans;text-align:center">✓</div></div>'
open('scenes/sc_w26.html','w').write(H+'<div class=p style="padding:90px 96px"><div style="font:900 72px MiSans;color:#15171C;line-height:1.25">以上全部用 <span class=pill>豆包工作</span><br>一键完成</div><div style="display:flex;gap:32px;margin-top:50px">'+mini('海外爆款','linear-gradient(160deg,#C9D6F2,#8EA7DE)')+mini('宠物用品','linear-gradient(160deg,#F2DCC9,#DDB08E)')+mini('卡点节奏','linear-gradient(160deg,#D5EDD9,#93C9A0)')+'</div></div><div class=tag style="left:auto;right:640px">缩略图换成 R1 成品截帧</div>')
